/*
 * A036349  Numbers whose sum of prime factors (taken with multiplicity) is
 *          even.
 * https://oeis.org/A036349
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = nth positive integer whose sum of prime factors * (with
 *            multiplicity) is even. The sequence can be generated by *
 *            testing each integer for even parity of its odd prime factors
 * Range:     u8 n <= 105, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

static const uint32_t SPF_LIMIT = 200000;          /* enough for ~10 000 terms */

/* Smallest prime factor table (global lazy‑initialized) */
static uint32_t *spf       = NULL;                 /* SPF array */
static size_t   spf_cap      = 0;

/* Builds the SPF table up to SPF_LIMIT. */
static void init_spf(void)
{
    spf_cap = SPF_LIMIT + 1;
    spf = (uint32_t *)malloc(spf_cap * sizeof(uint32_t));
    if (!spf) abort();

    for (size_t i = 0; i < spf_cap; ++i) spf[i] = 0;
    spf[0] = spf[1] = 1;

    for (size_t i = 2; i <= SPF_LIMIT; ++i) {
        if (spf[i] == 0) {                       /* i is prime */
            spf[i] = (uint32_t)i;
            if (i * i <= SPF_LIMIT) {
                for (size_t j = i * i; j <= SPF_LIMIT; j += i)
                    if (spf[j] == 0) spf[j] = (uint32_t)i;
            }
        }
    }
}

/* Returns true iff the sum of prime factors of x (with multiplicity)
 * is even.
 * 1 has an empty sum which is considered even. */
static bool even_sum_of_prime_factors(uint64_t x)
{
    if (x <= 1) return true;
    bool parity = false;                         /* parity of odd primes */
    while (x > 1) {
        uint32_t p;
        if (x <= SPF_LIMIT) p = spf[(size_t)x];
        else                p = (uint32_t)x;      /* fallback for safety */

        parity ^= (p & 1);                       /* toggle on odd p */
        x /= p;
    }
    return !parity;                              /* even parity -> true */
}

/* Cache of computed terms */
static seq_t  *cache       = NULL;
static size_t  cache_cap   = 0;
static idx_t   cache_len   = 0;
static idx_t   last_checked = 0;

/* The required function */
seq_t a(idx_t n)
{
    /* Initialise SPF table and cache once */
    if (!spf) init_spf();

    if (!cache) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (!cache) abort();
        cache[0] = (seq_t)1;                     /* first term */
        cache_len = 1;
        last_checked = 1;
    }

    /* Generate terms until we have at least n of them */
    while (cache_len < n) {
        ++last_checked;                          /* candidate number */
        if (even_sum_of_prime_factors((uint64_t)last_checked)) {
            if (cache_len == cache_cap) {
                cache_cap *= 2;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                if (!cache) abort();
            }
            cache[cache_len++] = (seq_t)last_checked;
        }
    }

    return cache[(size_t)(n - 1)];                /* 1‑based indexing */
}
